tool_input.old_string:
.nav-item__icon {
  display: block;
  width: 26px;
  height: 26px;
  flex: 0 0 26px;
  color: currentColor;
}

.nav-item__icon--custom {
  font-size: 26px;
}

.nav-item__icon--element {
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 26px;
  line-height: 26px;
}

tool_input.new_string:
.nav-item__icon {
  display: block;
  width: 28px;
  height: 28px;
  flex: 0 0 28px;
  color: currentColor;
  fill: none;
  stroke: currentColor;
  stroke-width: 1.5;
  stroke-linecap: round;
  stroke-linejoin: round;
}

.nav-item.active .nav-item__icon {
  fill: currentColor;
  stroke: none;
}

.nav-item__icon--custom {
  font-size: 28px;
}

.nav-item__icon--element {
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 28px;
  line-height: 28px;
}
